class AssessmentSystem:

    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        """Add a new student into self.students dict
        :param name: str, student name
        :param grade: int, student grade
        :param major: str, student major
        """
        if not name:
            raise ValueError('Student name cannot be an empty string.')
        if grade < 0:
            raise ValueError('Student grade must be a non-negative integer.')
        if not major:
            raise ValueError('Student major cannot be an empty string.')
        if name not in self.students:
            self.students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        """Add score of specific course for student in self.students
        :param name: str, student name
        :param course: str, course name
        :param score: int, course score
        """
        if not name or not isinstance(name, str):
            raise KeyError('Invalid student name')
        if not course or not isinstance(course, str):
            raise KeyError('Invalid course name')
        if not 0 <= score <= 100:
            raise ValueError('Score must be between 0 and 100')
        if name not in self.students:
            self.students[name] = {}
        self.students[name][course] = score

    def get_gpa(self, name):
        """Get average grade of one student.
        :param name: str, student name
        :return: if name is in students and this students have courses grade, return average grade(float)
                    or None otherwise
        """
        if name in self.students and 'scores' in self.students[name] and self.students[name]['scores']:
            scores = self.students[name]['scores']
            average_score = sum(scores) / len(scores)
            return round(average_score, 2)
        else:
            return None

    def get_all_students_with_fail_course(self):
        """Get all students who have any score blow 60
        :return: list of str ,student name
        """
        result = []
        for student, courses in self.students.items():
            if any((score < 60 for score in courses.values())):
                result.append(student)
        return result

    def get_course_average(self, course: str) -> float:
        """Get the average score of a specific course.
        :param course: str, course name
        :return: float, average scores of this course if anyone have score of this course, or None if nobody have records.
        """
        scores = []
        for student, student_data in self.students.items():
            if course in student_data.get('scores', {}):
                scores.append(student_data['scores'][course])
        if not scores:
            return None
        return sum(scores) / len(scores)

    def get_top_student(self):
        """Calculate every student's gpa with get_gpa method, and find the student with highest gpa
        :return: str, name of student whose gpa is highest
        """
        if not self.students:
            return None
        top_student = None
        highest_gpa = None
        for name, student_info in self.students.items():
            gpa = self.get_gpa(name)
            if gpa is not None and (highest_gpa is None or gpa > highest_gpa):
                top_student = name
                highest_gpa = gpa
        return top_student

