import unittest

class TestAssessmentSystem(unittest.TestCase):
    def setUp(self):
        self.system = AssessmentSystem()

    def test_get_gpa_with_no_students(self):
        self.assertIsNone(self.system.get_gpa('student 1'))

    def test_get_gpa_with_no_course_scores(self):
        self.system.add_student('student 1', 3, 'SE')
        self.assertIsNone(self.system.get_gpa('student 1'))

    def test_get_gpa_with_one_course_score(self):
        self.system.add_student('student 1', 3, 'SE')
        self.system.add_course_score('student 1', 'math', 94)
        self.assertEqual(self.system.get_gpa('student 1'), 94.0)

    def test_get_gpa_with_multiple_course_scores(self):
        self.system.add_student('student 1', 3, 'SE')
        self.system.add_course_score('student 1', 'math', 94)
        self.system.add_course_score('student 1', 'Computer Network', 92)
        self.assertEqual(self.system.get_gpa('student 1'), 93.0)

if __name__ == '__main__':
    unittest.main()
